def transform(grid, noise=5, k=3):
    """Downscale: each k x k block becomes one cell of its single non-noise color."""
    h,w=len(grid),len(grid[0])
    out=[]
    for bi in range(0,h,k):
        row=[]
        for bj in range(0,w,k):
            vals={grid[i][j] for i in range(bi,bi+k) for j in range(bj,bj+k)}-{noise}
            row.append(vals.pop() if len(vals)>=1 else noise)
        out.append(row)
    return out
